type QueryParamValue = string | number | boolean | undefined | null;

function isLikelyTimeoutFailure(err: unknown): boolean {
  if (err instanceof Error && err.name === 'TimeoutError') {
    return true;
  }
  if (err instanceof DOMException && err.name === 'AbortError') {
    return /timeout|timed out|aborted due to timeout/i.test(err.message);
  }
  if (err instanceof Error) {
    return /timeout|timed out|aborted due to timeout/i.test(err.message);
  }
  return false;
}

function reportingTimeoutMessage(endpoint: string): string {
  if (endpoint.startsWith('/reporting/')) {
    return 'Report generation timed out. Please retry in a moment or use a shorter reporting period.';
  }
  return 'The request timed out. Please try again.';
}

function isLikelyNetworkFailure(err: unknown): boolean {
  if (err instanceof TypeError) {
    return true;
  }
  if (err instanceof Error) {
    return /failed to fetch|networkerror|load failed|network request failed/i.test(err.message);
  }
  return false;
}

function looksLikePdfBytes(bytes: Uint8Array): boolean {
  return (
    bytes.length >= 5
    && bytes[0] === 0x25 // %
    && bytes[1] === 0x50 // P
    && bytes[2] === 0x44 // D
    && bytes[3] === 0x46 // F
    && bytes[4] === 0x2d // -
  );
}

/**
 * Ensure report downloads are real PDF bytes with application/pdf type.
 * Prevents browser PDF viewers from showing "Failed to load PDF document."
 * when the API accidentally returns JSON/text with a PDF content-type.
 */
async function ensurePdfBlob(response: Response): Promise<Blob> {
  const contentType = (response.headers.get('Content-Type') || '').toLowerCase();
  const arrayBuffer = await response.arrayBuffer();
  const bytes = new Uint8Array(arrayBuffer);

  if (looksLikePdfBytes(bytes)) {
    return new Blob([arrayBuffer], { type: 'application/pdf' });
  }

  if (contentType.includes('application/json') || contentType.includes('text/')) {
    let text = '';
    try {
      text = typeof TextDecoder !== 'undefined'
        ? new TextDecoder().decode(bytes)
        : String.fromCharCode(...Array.from(bytes));
    } catch {
      text = '';
    }
    let message = 'Downloaded report is not a valid PDF';
    try {
      const json = JSON.parse(text);
      message = json?.message || json?.error || message;
    } catch {
      // keep default
    }
    throw new Error(message);
  }

  throw new Error('Downloaded report is not a valid PDF');
}

