  async importAccountingFile(
    provider: string,
    file: File,
    options?: { runAgents?: boolean; runOrchestration?: boolean }
  ) {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('provider', provider);
    if (options?.runAgents === false) {
      formData.append('runAgents', 'false');
    }
    if (options?.runOrchestration === false) {
      formData.append('runOrchestration', 'false');
    }

    try {
      return await this.requestFirstAvailable([
        '/transactions/import-accounting-file',
        '/accounting/import-accounting-file',
      ], {
        method: 'POST',
        body: formData,
      });
    } catch (err) {
      if (!this.isRouteNotFoundError(err)) {
        throw err;
      }

      const transactions = await parseAccountingImportFileClientSide(file);
      return this.importAccountingTransactions({
        provider,
        transactions,
        runAgents: options?.runAgents,
        runOrchestration: options?.runOrchestration,
      });
    }
  }

