  // Incentives endpoints
  private mapIncentiveRewards(rewards: unknown[]) {
    return (Array.isArray(rewards) ? rewards : []).map((reward) => {
      const entry = reward as {
        rewardId?: string;
        id?: string;
        title?: string;
        description?: string;
        cost?: number;
        category?: string;
        available?: boolean;
      };
      return {
        id: entry.rewardId ?? entry.id ?? '',
        title: entry.title ?? '',
        description: entry.description ?? '',
        cost: entry.cost ?? 0,
        category: entry.category ?? 'general',
        available: entry.available !== false,
      };
    });
  }

  private unwrapApiData<T>(response: unknown): T {
    if (response && typeof response === 'object' && 'data' in response) {
      return (response as ApiResponse<T>).data as T;
    }
    return response as T;
  }

  private async getIncentivesFromLegacyRoutes(): Promise<ApiResponse> {
    const [statsResponse, dailyTasksResponse, leaderboardResponse] = await Promise.all([
      this.request('/incentives/stats'),
      this.request('/incentives/daily-tasks'),
      this.request('/incentives/leaderboard'),
    ]);

    const statsPayload = this.unwrapApiData<Record<string, unknown>>(statsResponse);
    const rewards = Array.isArray(statsPayload?.rewards) ? statsPayload.rewards : [];

    return {
      success: true,
      data: {
        incentives: this.mapIncentiveRewards(rewards),
        userStats: statsPayload?.userStats,
        achievements: statsPayload?.achievements,
        rewards,
        dailyTasks: this.unwrapApiData<unknown[]>(dailyTasksResponse) ?? [],
        leaderboard: this.unwrapApiData<unknown[]>(leaderboardResponse) ?? [],
      },
    };
  }

  private async getFinanceOverviewFromLegacySignals(): Promise<ApiResponse> {
    const [profileResponse, incentivesResponse] = await Promise.all([
      this.getMSMEProfile().catch(() => null),
      this.getIncentives().catch(() => null),
    ]);

    const profile = this.unwrapApiData<Record<string, unknown>>(profileResponse);
    const incentivesData = this.unwrapApiData<Record<string, unknown>>(incentivesResponse);
    const achievements = Array.isArray(incentivesData?.achievements)
      ? (incentivesData.achievements as Array<{ id?: string; progress?: number }>)
      : [];
    const userStats = (incentivesData?.userStats ?? {}) as Record<string, unknown>;
    const assessmentAchievement = achievements.find((item) => item.id === 'achv_assessments');
    const recommendationAchievement = achievements.find((item) => item.id === 'achv_reco');
    const assessmentCount = Number(assessmentAchievement?.progress ?? 0);
    const implementedRecommendations = Number(recommendationAchievement?.progress ?? 0);
    const carbonSavedKg = Number(userStats.carbonSaved ?? 0);
    const latestCarbonScore = Number(profile?.carbonScore ?? 0);

    const buildOption = (
      id: string,
      title: string,
      description: string,
      path: string,
      ctaLabel: string
    ) => ({
      id,
      title,
      description,
      path,
      category: 'finance',
      isEligible: false,
      status: 'in_progress',
      criteria: [],
      ctaLabel,
    });

    const options = [
      buildOption(
        'adeetie',
        'ADEETIE (BEE)',
        'Energy-efficiency interest subvention and handholding.',
        '/adeetie',
        'Open ADEETIE hub'
      ),
      buildOption(
        'green_loans',
        'Green loans',
        'Bank-backed finance for solar, efficiency, and other green projects.',
        '/green-loans',
        'Check eligibility'
      ),
      buildOption(
        'gift_schemes',
        'GIFT schemes',
        'Government incentive schemes matched to your MSME profile.',
        '/gift-schemes',
        'Browse schemes'
      ),
      {
        id: 'gift_applications',
        title: 'My applications',
        description: 'Track submitted GIFT and ADEETIE-linked applications.',
        path: '/gift-applications',
        category: 'workflow',
        isEligible: true,
        status: 'in_progress',
        criteria: [],
        ctaLabel: 'View applications',
      },
    ];

    const nextSteps = [];
    if (assessmentCount <= 0) {
      nextSteps.push({
        id: 'run_assessment',
        label: 'Run a carbon assessment',
        description: 'Required for green loan and scheme eligibility checks.',
        path: '/carbon-footprint?section=start-assessment',
      });
    }
    if (implementedRecommendations < 3) {
      nextSteps.push({
        id: 'implement_reco',
        label: 'Implement sustainability recommendations',
        description: 'Past reduction actions strengthen finance and incentive applications.',
        path: '/carbon-footprint?section=recommendations',
      });
    }

    return {
      success: true,
      data: {
        companyName: String(profile?.companyName ?? 'Your company'),
        emissionsAchievements: {
          assessmentCount,
          implementedRecommendations,
          energyRecommendationsImplemented: 0,
          latestCarbonScore: Number.isFinite(latestCarbonScore) && latestCarbonScore > 0
            ? latestCarbonScore
            : null,
          absoluteReductionKg: 0,
          reductionPercent: 0,
          carbonSavedKg,
          savingsPercent: 0,
          reductionTargetPct: null,
          targetProgressPercent: null,
          hasAssessment: assessmentCount > 0,
          hasReductionHistory: false,
        },
        summary: {
          eligibleCount: 0,
          inProgressCount: options.length - 1,
          totalOptions: options.length - 1,
          headline:
            'Explore finance and incentive options below. Full eligibility scoring will appear after the workspace API syncs.',
        },
        options,
        nextSteps: nextSteps.slice(0, 4),
      },
    };
  }

