  async exportReportArtifact(params: {
    reportType: string;
    format: string;
    dateRange: string;
    reportId?: string;
  }): Promise<{ blob: Blob; fileName: string }> {
    const url = `${API_BASE_URL}/reporting/export`;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    const token = getClientAccessToken();
    if (token) {
      headers.Authorization = `Bearer ${token}`;
    }

    const response = await fetch(url, this.buildFetchInit({
      method: 'POST',
      headers,
      body: JSON.stringify({
        reportType: params.reportType,
        format: params.format,
        dateRange: params.dateRange,
        reportId: params.reportId || `EXP-${Date.now()}`,
      }),
    }, this.resolveRequestTimeoutMs('/reporting/export')));

    const contentType = response.headers.get('Content-Type') || '';
    const disposition = response.headers.get('Content-Disposition');

    if (!response.ok) {
      const errorBody = contentType.includes('application/json')
        ? await response.json()
        : await response.text();
      throw this.createHttpError(errorBody, response.status, '/reporting/export');
    }

    if (contentType.includes('application/json')) {
      const json = await response.json();
      const payload = json?.data ?? json;
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const fallbackName = `${params.reportType}_${params.format}_${new Date().toISOString().slice(0, 10)}.json`;
      return {
        blob,
        fileName: this.parseContentDispositionFilename(disposition, fallbackName),
      };
    }

    const blob = await response.blob();
    const fallbackName = `${params.reportType}_${params.format}_${new Date().toISOString().slice(0, 10)}`;
    return {
      blob,
      fileName: this.parseContentDispositionFilename(disposition, fallbackName),
    };
  }

