  // Compliance hub (India + export tracks)
  private async buildComplianceLegacySignals(period = 'annual') {
    const enterpriseProfile = await this.getEnterpriseProfile().catch(() => null);
    const useEnterprise = Boolean(enterpriseProfile?.data?.companyName);

    const [profileResponse, statsResponse, brsrResponse] = await Promise.all([
      useEnterprise
        ? Promise.resolve(enterpriseProfile)
        : this.getMSMEProfile().catch(() => null),
      useEnterprise ? Promise.resolve(null) : this.getMSMEStats().catch(() => null),
      this.getBRSRReport({ period }).catch(() => null),
    ]);

    const profile = this.unwrapApiData<Record<string, unknown>>(profileResponse);
    const stats = this.unwrapApiData<Record<string, unknown>>(statsResponse);
    const brsr = this.unwrapApiData<Record<string, unknown>>(brsrResponse);
    const carbon = (stats?.carbon ?? {}) as Record<string, unknown>;
    const brsrCompliance = (brsr?.compliance ?? {}) as Record<string, unknown>;
    const brsrEmissions = (brsr?.emissions ?? {}) as Record<string, unknown>;
    const totalEmissionsKg = Number(
      carbon.totalCO2Emissions ?? brsrEmissions.totalGHG ?? 0
    );
    const hasEmissions = Number.isFinite(totalEmissionsKg) && totalEmissionsKg > 0;
    const brsrReady = Boolean(
      brsrCompliance.isBRSRCompliant || brsrCompliance.disclosurePrepReady
    );

    return {
      period,
      companyName: String(profile?.companyName ?? 'Your company'),
      totalEmissionsKg,
      hasEmissions,
      brsrReady,
      brsr,
    };
  }

  private buildComplianceIndiaReadiness(signals: {
    hasEmissions: boolean;
    brsrReady: boolean;
  }) {
    return {
      brsrCore: signals.brsrReady
        ? 'aligned'
        : signals.hasEmissions
          ? 'needs_improvement'
          : 'needs_activity_data',
      isoAssurance: 'in_progress',
      patIntensity: signals.hasEmissions ? 'data_available' : 'needs_activity_data',
      sbti: 'not_started',
      zedCertification: 'not_started',
      accountingSync: 'import_only',
    };
  }

  private buildComplianceExportReadiness(signals: { hasEmissions: boolean }) {
    return {
      cbam: 'review_required',
      productPcf: 'needs_products',
      csrd: signals.hasEmissions ? 'datapoints_available' : 'needs_inventory',
      cdp: signals.hasEmissions ? 'datapoints_available' : 'needs_inventory',
      tcfd: 'template_ready',
      supplierPortal: 'empty',
      eudr: 'not_applicable',
      ecovadis: 'template_ready',
    };
  }

  private async buildComplianceFallback(
    track: 'overview' | 'india' | 'export',
    params?: { period?: string }
  ): Promise<ApiResponse> {
    const signals = await this.buildComplianceLegacySignals(params?.period ?? 'annual');
    const indiaReadiness = this.buildComplianceIndiaReadiness(signals);
    const exportReadiness = this.buildComplianceExportReadiness(signals);
    const generatedAt = new Date().toISOString();

    if (track === 'overview') {
      return {
        success: true,
        data: {
          period: signals.period,
          companyName: signals.companyName,
          totalEmissionsKgCo2e: signals.totalEmissionsKg,
          indiaReadiness,
          exportReadiness,
          generatedAt,
        },
      };
    }

    if (track === 'india') {
      return {
        success: true,
        data: {
          track: 'india',
          period: signals.period,
          generatedAt,
          readiness: indiaReadiness,
          modules: {
            brsrCoreSupplierPack: signals.brsr ?? {},
            iso14064Assurance: { overallReadinessScore: 0, checkpoints: [] },
            patEnergyIntensity: { energySharePercent: signals.hasEmissions ? 1 : 0 },
            sbtiTargets: { status: 'not_started' },
            actionPlans: [],
            productFootprints: [],
            zedCertification: {},
            accountingSync: [],
          },
        },
      };
    }

    return {
      success: true,
      data: {
        track: 'export',
        period: signals.period,
        generatedAt,
        exportProfile: {},
        readiness: exportReadiness,
        modules: {
          cbamExporter: {},
          productFootprints: [],
          csrdSupplier: {},
          cdpClimate: {},
          tcfdIssb: {},
          supplierQuestionnaires: [],
          eudr: { applicable: false },
          ecovadis: {},
        },
        packValidation: {},
      },
    };
  }

  private async requestComplianceReadEndpoint(
    track: 'overview' | 'india' | 'export',
    params?: { period?: string }
  ): Promise<ApiResponse> {
    const query = this.buildQueryString({ period: params?.period });
    const pathByTrack = {
      overview: ['/compliance-hub/overview', '/compliance/overview'],
      india: ['/compliance-hub/india', '/compliance/india'],
      export: ['/compliance-hub/export', '/compliance/export'],
    };
    const primaryPath = pathByTrack[track][0];
    const cacheKey = buildApiCacheKey('GET', primaryPath, query.replace(/^\?/, ''));

    return cachedApiGet(cacheKey, API_CACHE_TTL.complianceHubMs, async () => {
      try {
        return await this.requestFirstAvailable(
          pathByTrack[track].map((path) => `${path}${query}`)
        );
      } catch (err) {
        if (!this.isRouteNotFoundError(err)) {
          throw err;
        }
        return this.buildComplianceFallback(track, params);
      }
    });
  }

